revoke execute on function public.get_my_education_pilots() from authenticated; create or replace function public.get_my_scholarship_matches(p_limit integer default 25) returns table(opportunity_id uuid,title text,institution text,study_country text,funding_type text,deadline date,eligibility_score integer,eligible boolean,checks jsonb) language sql stable set search_path to '' as $$ select o.id,o.title,s.institution,s.study_country,s.funding_type,o.deadline,coalesce((e.j->>'score')::int,0),coalesce((e.j->>'eligible')::boolean,false),coalesce(e.j->'checks','[]'::jsonb) from public.opportunities o join public.scholarship_details s on s.opportunity_id=o.id cross join lateral (select public.check_scholarship_eligibility(o.id) as j) e where public.my_audience_feature_access('scholarships') in ('enabled','limited','adult_gate') and o.opportunity_type='scholarships'::public.opportunity_type and o.status='open' and o.verified_active=true and o.deadline>=current_date order by coalesce((e.j->>'eligible')::boolean,false) desc,coalesce((e.j->>'score')::int,0) desc,o.deadline asc limit greatest(1,least(coalesce(p_limit,25),100)); $$;
